# Analyze potential patterns - look for rectangular shapes

def find_rectangles_in_grid(grid):
    """Find potential rectangles formed by 6s"""
    rows, cols = len(grid), len(grid[0])

    # Check for rectangular frames
    rectangles = []

    for r1 in range(rows):
        for c1 in range(cols):
            if grid[r1][c1] != 6:
                continue

            # Try extending to form a rectangle
            for r2 in range(r1, rows):
                for c2 in range(c1, cols):
                    # Check if we have a complete rectangular frame
                    # Top row
                    top_ok = all(grid[r1][c] == 6 for c in range(c1, c2 + 1))
                    # Bottom row
                    bottom_ok = all(grid[r2][c] == 6 for c in range(c1, c2 + 1))
                    # Left column
                    left_ok = all(grid[r][c1] == 6 for r in range(r1, r2 + 1))
                    # Right column
                    right_ok = all(grid[r][c2] == 6 for r in range(r1, r2 + 1))

                    if top_ok and bottom_ok and left_ok and right_ok:
                        # Check if interior is not all 6s (optional)
                        interior_empty = True
                        for r in range(r1 + 1, r2):
                            for c in range(c1 + 1, c2):
                                if grid[r][c] == 6:
                                    interior_empty = False
                                    break
                            if not interior_empty:
                                break

                        rect = (r1, c1, r2, c2, interior_empty)
                        if rect not in rectangles:
                            rectangles.append(rect)

    return rectangles

rectangles = find_rectangles_in_grid(grid)
print(f"Found {len(rectangles)} rectangular frames")

for i, rect in enumerate(rectangles[:15]):
    r1, c1, r2, c2, empty_interior = rect
    print(f"Rect {i}: ({r1},{c1}) to ({r2},{c2}), interior_empty={empty_interior}, size={(r2-r1)*(c2-c1)+4}")

# Check for holes/enclosed regions inside the rectangles

def find_enclosed_regions(grid):
    """Find 0-regions (background) that are completely surrounded by another color"""
    rows, cols = len(grid), len(grid[0])

    # First, identify which background cells can reach the edge
    from collections import deque

    visited = set()
    q = deque()

    # Start from all edge cells
    for c in range(cols):
        if grid[0][c] == 3:
            q.append((0, c))
            visited.add((0, c))
        if grid[-1][c] == 3:
            q.append((rows - 1, c))
            visited.add((rows - 1, c))

    for r in range(rows):
        if grid[r][0] == 3 and (r, 0) not in visited:
            q.append((r, 0))
            visited.add((r, 0))
        if grid[r][-1] == 3 and (r, cols - 1) not in visited:
            q.append((r, cols - 1))
            visited.add((r, cols - 1))

    while q:
        r, c = q.popleft()
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 3 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))

    # Cells not visited are enclosed
    enclosed = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3 and (r, c) not in visited:
                enclosed.append((r, c))

    return enclosed

enclosed = find_enclosed_regions(grid)
print(f"Number of enclosed regions: {len(enclosed)}")
if enclosed:
    print(f"Enclosed region coordinates: {enclosed}")

    # Check if they form a rectangle
    rows_enc = sorted(set(r for r, c in enclosed))
    cols_enc = sorted(set(c for r, c in enclosed))
    print(f"Enclosed spans rows {min(rows_enc)}-{max(rows_enc)}, cols {min(cols_enc)}-{max(cols_enc)}")

