# Count endpoints (6s with only 1 neighbor)
def find_endpoints(grid):
    """Find pixels of value 6 that have exactly one adjacent 6"""
    rows, cols = len(grid), len(grid[0])
    endpoints = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 6:
                continue

            neighbors = sum(1 for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)] 
                          if 0 <= r+dr < rows and 0 <= c+dc < cols and grid[r+dr][c+dc] == 6)

            if neighbors == 1:
                endpoints.append((r, c))

    return endpoints

